using System.Linq;
namespace RecursiveAI.OneDocument.Accessibility;

/// <summary>
/// How serious an accessibility finding is, in the words of Office's published rule set: an error makes content hard or impossible to use
/// with assistive technology, a warning does so in most cases, a tip is content that could be presented better. The fourth group lists
/// content generated by an automatic service that a person should review.
/// </summary>
public enum AccessibilityCategory
{
    /// <summary>Content that is difficult or impossible to read and understand for people with disabilities.</summary>
    Error = 0,

    /// <summary>Content that in most (but not all) cases is difficult to understand for people with disabilities.</summary>
    Warning = 1,

    /// <summary>Content that can be understood but could be presented in a way that improves the experience.</summary>
    Tip = 2,

    /// <summary>Content that was made accessible automatically and should be reviewed for accuracy.</summary>
    IntelligentServices = 3,
}

/// <summary>One accessibility rule: our stable identifier, the Office rule it corresponds to (when it does) and its category.</summary>
public sealed class AccessibilityRule
{
    private readonly byte _kinds;

    internal AccessibilityRule(string id, string name, string? officeRule, AccessibilityCategory category, string description, params OfficeKind[] kinds)
    {
        Id = id;
        Name = name;
        OfficeRule = officeRule;
        Category = category;
        Description = description;
        foreach (OfficeKind k in kinds)
        {
            _kinds |= (byte)(1 << (int)k);
        }
    }

    /// <summary>Gets the stable rule identifier, such as <c>alt-text.missing</c>. Identifiers are never reused or renumbered.</summary>
    public string Id { get; }

    /// <summary>Gets a short name for the finding, in plain words.</summary>
    public string Name { get; }

    /// <summary>
    /// Gets the name of the rule in Office's published list that this finding falls under, or null for a check that OneDocument adds
    /// (Office's guidance asks for it but its list names no rule).
    /// </summary>
    public string? OfficeRule { get; }

    /// <summary>Gets the category.</summary>
    public AccessibilityCategory Category { get; }

    /// <summary>Gets what the rule checks.</summary>
    public string Description { get; }

    /// <summary>Tells whether the rule is evaluated for a kind of document.</summary>
    /// <param name="kind">The kind.</param>
    /// <returns>True when the rule applies to documents of that kind.</returns>
    public bool AppliesTo(OfficeKind kind) => (_kinds & (1 << (int)kind)) != 0;

    /// <inheritdoc/>
    public override string ToString() => Id;
}

/// <summary>The catalogue of accessibility rules, in the order they are documented.</summary>
public static class AccessibilityRules
{
    private const OfficeKind D = OfficeKind.Document;
    private const OfficeKind W = OfficeKind.Workbook;
    private const OfficeKind P = OfficeKind.Presentation;

    private const string AltRule = "All non-text content has alternative text";
    private const string HeaderRule = "Tables specify column header information";
    private const string SimpleRule = "Table has a simple structure";

    /// <summary>A picture, shape, chart, diagram, group or embedded object has no alternative text and is not marked decorative.</summary>
    public static AccessibilityRule AltTextMissing { get; } = new("alt-text.missing", "Missing alternative text", AltRule, AccessibilityCategory.Error,
        "Pictures, shapes, charts, diagrams, groups, embedded objects and media have alternative text unless marked decorative.", D, W, P);

    /// <summary>The alternative text is a file name or ends in a file extension.</summary>
    public static AccessibilityRule AltTextFileName { get; } = new("alt-text.file-name", "Alternative text is a file name", AltRule, AccessibilityCategory.Error,
        "Alternative text does not contain an image name or file extension.", D, W, P);

    /// <summary>The alternative text was generated by an automatic service and has not been edited.</summary>
    public static AccessibilityRule AltTextSuggested { get; } = new("alt-text.suggested", "Suggested alternative text", "Suggested alternative text", AccessibilityCategory.IntelligentServices,
        "Alternative text that carries the marker an automatic image-description service appends; review it for accuracy.", D, P);

    /// <summary>A table has no header row.</summary>
    public static AccessibilityRule TableHeaderRow { get; } = new("table.header-row", "Table without a header row", HeaderRule, AccessibilityCategory.Error,
        "A table marks its first row as the header row.", D, W, P);

    /// <summary>A table has merged cells.</summary>
    public static AccessibilityRule TableMergedCells { get; } = new("table.merged-cells", "Merged cells", SimpleRule, AccessibilityCategory.Warning,
        "A table is a simple rectangle without merged cells.", D, W, P);

    /// <summary>The rows of a table do not have the same number of columns (split cells).</summary>
    public static AccessibilityRule TableIrregularGrid { get; } = new("table.irregular-grid", "Split cells", SimpleRule, AccessibilityCategory.Warning,
        "Every row of a table has the same number of columns.", D, P);

    /// <summary>A table sits inside a cell of another table.</summary>
    public static AccessibilityRule TableNested { get; } = new("table.nested", "Nested table", SimpleRule, AccessibilityCategory.Warning,
        "A table is not nested inside another table.", D);

    /// <summary>A row or column of a table is entirely blank.</summary>
    public static AccessibilityRule TableBlankCells { get; } = new("table.blank-cells", "Blank table row or column", null, AccessibilityCategory.Warning,
        "Rows or columns of empty cells are not used for spacing.", D, P);

    /// <summary>A workbook table keeps its generated name.</summary>
    public static AccessibilityRule TableDefaultName { get; } = new("table.default-name", "Table name left at its default", null, AccessibilityCategory.Tip,
        "Tables have a descriptive name rather than Table1, Table2, ….", W);

    /// <summary>Text and its background are too close in luminance.</summary>
    public static AccessibilityRule ContrastLow { get; } = new("contrast.low", "Insufficient contrast", "Sufficient contrast between text and background", AccessibilityCategory.Warning,
        "Text has a contrast ratio of at least 4.5:1 against its background (3:1 for large text).", D, W, P);

    /// <summary>The file has no title in its properties.</summary>
    public static AccessibilityRule DocumentTitle { get; } = new("document.title", "No document title", null, AccessibilityCategory.Tip,
        "The title property is set.", D, W, P);

    /// <summary>No language is declared for the content.</summary>
    public static AccessibilityRule DocumentLanguage { get; } = new("document.language", "No language declared", null, AccessibilityCategory.Tip,
        "A proofing language is declared, so screen readers pick the right voice.", D, P);

    /// <summary>A content control has no title.</summary>
    public static AccessibilityRule ContentControlTitle { get; } = new("content-control.title", "Content control without a title", "All content control fields have titles", AccessibilityCategory.Error,
        "Every content control has a title (alias).", D);

    /// <summary>A long document uses no headings and no table of contents.</summary>
    public static AccessibilityRule HeadingsMissing { get; } = new("headings.missing", "No headings", "Documents use heading styles", AccessibilityCategory.Tip,
        "Long documents are organized with heading styles or a table of contents.", D);

    /// <summary>A heading level is skipped.</summary>
    public static AccessibilityRule HeadingsSkipped { get; } = new("headings.skipped", "Heading level skipped", null, AccessibilityCategory.Tip,
        "Headings go down one level at a time.", D);

    /// <summary>A run of spaces or tabs is used for spacing.</summary>
    public static AccessibilityRule SpacingBlankCharacters { get; } = new("spacing.blank-characters", "Repeated blank characters", null, AccessibilityCategory.Tip,
        "Paragraph spacing and indents are used instead of runs of spaces or tabs.", D);

    /// <summary>Empty paragraphs are used for spacing.</summary>
    public static AccessibilityRule SpacingBlankParagraphs { get; } = new("spacing.blank-paragraphs", "Repeated blank paragraphs", null, AccessibilityCategory.Tip,
        "Paragraph spacing is used instead of consecutive empty paragraphs.", D);

    /// <summary>A picture or shape floats instead of sitting in the text line.</summary>
    public static AccessibilityRule FloatingObject { get; } = new("floating.object", "Floating object", null, AccessibilityCategory.Warning,
        "Pictures and shapes are placed in line with the text.", D);

    /// <summary>Link text says nothing about where the link goes.</summary>
    public static AccessibilityRule HyperlinkText { get; } = new("hyperlink.text", "Hyperlink text is not meaningful", null, AccessibilityCategory.Warning,
        "Link text describes the target; it is not “click here”, a bare address or empty.", D, W, P);

    /// <summary>A picture is used as a watermark.</summary>
    public static AccessibilityRule WatermarkImage { get; } = new("watermark.image", "Image watermark", null, AccessibilityCategory.Warning,
        "Watermarks that are pictures are not read by assistive technology.", D);

    /// <summary>A sheet keeps its generated name.</summary>
    public static AccessibilityRule SheetDefaultName { get; } = new("sheet.default-name", "Sheet name left at its default", "Sheet tabs have meaningful names", AccessibilityCategory.Warning,
        "Sheets have descriptive names rather than Sheet1, Sheet2, ….", W);

    /// <summary>A sheet has no content.</summary>
    public static AccessibilityRule SheetBlank { get; } = new("sheet.blank", "Blank sheet", "Sheet tabs have meaningful names", AccessibilityCategory.Warning,
        "There are no blank sheets.", W);

    /// <summary>Negative numbers differ from positive ones by red colour only.</summary>
    public static AccessibilityRule NumberFormatRedOnly { get; } = new("number-format.red-only", "Red-only negative numbers", "Cells in an Excel worksheet don't use red-only formatting for negative numbers", AccessibilityCategory.Error,
        "A number format that shows negative numbers in red also shows a minus sign or parentheses.", W);

    /// <summary>A slide has no title.</summary>
    public static AccessibilityRule SlideTitleMissing { get; } = new("slide.title-missing", "Slide without a title", "All slides have titles", AccessibilityCategory.Error,
        "Every slide has a non-empty title.", P);

    /// <summary>Two slides have the same title.</summary>
    public static AccessibilityRule SlideTitleDuplicate { get; } = new("slide.title-duplicate", "Duplicate slide title", "Slide titles in a deck are unique", AccessibilityCategory.Tip,
        "Non-blank slides have unique titles.", P);

    /// <summary>The title is not first in the reading order of a slide.</summary>
    public static AccessibilityRule SlideReadingOrder { get; } = new("slide.reading-order", "Reading order", "The reading order of the objects on a slide presentation is logical", AccessibilityCategory.Warning,
        "The title comes first in the reading order (the bottom of the stacking order) of a slide.", P);

    /// <summary>A section has a placeholder name.</summary>
    public static AccessibilityRule SectionDefaultName { get; } = new("section.default-name", "Section name left at its default", "All sections have meaningful names", AccessibilityCategory.Error,
        "Sections are not named “Default Section”, “Untitled Section” or “Section N”.", P);

    /// <summary>Two sections have the same name.</summary>
    public static AccessibilityRule SectionDuplicateName { get; } = new("section.duplicate-name", "Duplicate section name", "The section names in a deck are unique", AccessibilityCategory.Tip,
        "Section names are unique.", P);

    /// <summary>Audio or video has no closed captions.</summary>
    public static AccessibilityRule MediaCaptions { get; } = new("media.captions", "Media without captions", "Closed captions are included for inserted audio and video", AccessibilityCategory.Warning,
        "Audio and video objects have a captions track.", P);

    /// <summary>Gets every rule.</summary>
    public static IReadOnlyList<AccessibilityRule> All { get; } =
    [
        AltTextMissing, AltTextFileName, AltTextSuggested, TableHeaderRow, TableMergedCells, TableIrregularGrid, TableNested, TableBlankCells, TableDefaultName,
        ContrastLow, DocumentTitle, DocumentLanguage, ContentControlTitle, HeadingsMissing, HeadingsSkipped, SpacingBlankCharacters, SpacingBlankParagraphs,
        FloatingObject, HyperlinkText, WatermarkImage, SheetDefaultName, SheetBlank, NumberFormatRedOnly, SlideTitleMissing, SlideTitleDuplicate,
        SlideReadingOrder, SectionDefaultName, SectionDuplicateName, MediaCaptions,
    ];

    /// <summary>Gets the rules evaluated for one kind of document.</summary>
    /// <param name="kind">The kind.</param>
    /// <returns>The rules that apply, in catalogue order.</returns>
    public static IReadOnlyList<AccessibilityRule> For(OfficeKind kind) => [.. All.Where(r => r.AppliesTo(kind))];

    /// <summary>Finds a rule by identifier.</summary>
    /// <param name="id">The identifier, such as <c>table.header-row</c>.</param>
    /// <returns>The rule, or null when there is none.</returns>
    public static AccessibilityRule? Find(string id) => All.FirstOrDefault(r => r.Id == id);
}
